      'Zentrum für Lebenshinweise: Kleidung, Schirm, UV, Autowäsche, Sport und Wäsche',
      'Neue Extremwetter-Leiste oben: Hitze, Kälteeinbruch, Sturm, starke UV und Starkregen',
      'Neues „Frische“-Abzeichen auf jeder Karte: Live oder Cache sofort erkennbar',
      'Vollständige Geräteerkennung: sichere Bereiche und Abstände je Gerätefamilie, für Notch, Dynamic Island und Gestennavigation',
