Object.entries(V271_STRINGS).forEach(([lang, dict]) => {
  if (!TRANSLATIONS[lang]) return;
  Object.assign(TRANSLATIONS[lang], dict);
});

// ==================== i18n API ====================

let currentLang = 'zh-CN';
let listeners = [];

function detectBrowserLanguage() {
  const lang = (navigator.language || 'zh-CN').toLowerCase();
  if (lang.startsWith('zh-tw') || lang.startsWith('zh-hk') || lang.startsWith('zh-mo')) return 'zh-TW';
  if (lang.startsWith('zh')) return 'zh-CN';
  if (lang.startsWith('ja')) return 'ja';
  if (lang.startsWith('ko')) return 'ko';
  if (lang.startsWith('fr')) return 'fr';
  if (lang.startsWith('de')) return 'de';
  if (lang.startsWith('es')) return 'es';
  if (lang.startsWith('pt')) return 'pt';
  if (lang.startsWith('ru')) return 'ru';
  if (lang.startsWith('en')) return 'en';
  return 'zh-CN';
}

export function initI18n(savedLang) {
  if (savedLang && TRANSLATIONS[savedLang]) {
    currentLang = savedLang;
  } else {
    currentLang = detectBrowserLanguage();
  }
  document.documentElement.setAttribute('lang', currentLang);
  applyDirection();
}

function applyDirection() {
  // 所有10种语言都是LTR
  document.documentElement.setAttribute('dir', 'ltr');
}

export function getLanguage() {
  return currentLang;
}

export function getLanguages() {
  return Object.keys(LANGUAGES).map((code) => ({
    code,
    name: LANGUAGES[code].name,
    native: LANGUAGES[code].native,
  }));
}

export function setLanguage(lang) {
  if (!TRANSLATIONS[lang]) return false;
  currentLang = lang;
  document.documentElement.setAttribute('lang', lang);
  applyDirection();
  listeners.forEach((fn) => fn(lang));
  return true;
}

export function onLanguageChange(fn) {
  listeners.push(fn);
  return () => {
    listeners = listeners.filter((l) => l !== fn);
  };
}

