Object.keys(TRANSLATIONS).forEach((lang) => {
  Object.assign(TRANSLATIONS[lang], SYNC_STRINGS[lang] || SYNC_STRINGS.en);
});

/**
 * 翻译函数
 * t('key') — 普通翻译
 * t('key', 'arg1', 'arg2') — 带占位符 $1, $2...
 */
export function t(key, ...args) {
  const dict = TRANSLATIONS[currentLang] || TRANSLATIONS['zh-CN'];
  let value = dict[key];

  if (value === undefined) {
    // 回退到中文
    value = TRANSLATIONS['zh-CN'][key];
  }

  if (value === undefined) {
    console.warn('[APEXON i18n] Missing key:', key, 'lang:', currentLang);
    return key;
  }

  // 处理数组类型（如更新日志）
  if (Array.isArray(value)) {
    return value;
  }

  // 替换占位符 $1, $2, ...
  args.forEach((arg, i) => {
    value = value.replace(new RegExp(`\\$${i + 1}`, 'g'), arg);
  });

  return value;
}

export default {
  init: initI18n,
  t,
  getLanguage,
  getLanguages,
  setLanguage,
  onLanguageChange,
};
